def deep_merge_keep_existing(target, additions):
    """Recursively add keys from `additions` into `target`, but never overwrite
    keys that already exist in `target`."""
    for key, value in additions.items():
        if isinstance(value, dict):
            if key not in target or not isinstance(target.get(key), dict):
                target[key] = OrderedDict()
            deep_merge_keep_existing(target[key], value)
        else:
            if key not in target:
                target[key] = value


def main():
    # English first (source-of-truth)
    en_path = LOCALES_DIR / "en.json"
    with en_path.open("r", encoding="utf-8") as f:
        en_data = json.load(f, object_pairs_hook=OrderedDict)
    deep_merge_keep_existing(en_data, EN)
    with en_path.open("w", encoding="utf-8") as f:
        json.dump(en_data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print("  OK:   en.json")

    # All non-EN locales
    for locale_code, additions in TRANSLATIONS.items():
        path = LOCALES_DIR / f"{locale_code}.json"
        if not path.exists():
            print(f"  SKIP: {path.name} (not found)")
            continue
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f, object_pairs_hook=OrderedDict)
        deep_merge_keep_existing(data, additions)
        with path.open("w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print(f"  OK:   {path.name}")


if __name__ == "__main__":
    main()
